-- Demo trading platform - SQLite schema (development/test).
-- All timestamps are Unix epoch milliseconds (INTEGER), generated by the server.
-- All money amounts are integer minor units ("cents") to avoid floating point drift.

CREATE TABLE IF NOT EXISTS schema_migrations (
  name        TEXT PRIMARY KEY,
  applied_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
  id              TEXT PRIMARY KEY,
  email           TEXT NOT NULL,
  email_normalized TEXT NOT NULL UNIQUE,
  password_hash   TEXT NOT NULL,
  role            TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  created_at      INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS accounts (
  user_id       TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  balance_cents INTEGER NOT NULL CHECK (balance_cents >= 0),
  currency      TEXT NOT NULL DEFAULT 'USD',
  updated_at    INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS trades (
  id              TEXT PRIMARY KEY,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  symbol          TEXT NOT NULL,
  direction       TEXT NOT NULL CHECK (direction IN ('up', 'down')),
  amount_cents    INTEGER NOT NULL CHECK (amount_cents > 0),
  duration_sec    INTEGER NOT NULL CHECK (duration_sec > 0),
  entry_price     REAL NOT NULL,
  entry_time      INTEGER NOT NULL,
  expiry_time     INTEGER NOT NULL,
  close_price     REAL,
  settled_at      INTEGER,
  status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  result          TEXT CHECK (result IN ('win', 'lose', 'draw')),
  payout_rate     REAL NOT NULL,
  payout_mode     TEXT NOT NULL CHECK (payout_mode IN ('profit', 'total')),
  payout_cents    INTEGER NOT NULL DEFAULT 0 CHECK (payout_cents >= 0),
  idempotency_key TEXT,
  request_hash    TEXT,
  created_at      INTEGER NOT NULL,
  CHECK (status = 'open' OR (result IS NOT NULL AND close_price IS NOT NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_trades_idempotency
  ON trades(user_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS ix_trades_due ON trades(status, expiry_time);
CREATE INDEX IF NOT EXISTS ix_trades_user ON trades(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS candles (
  symbol TEXT NOT NULL,
  tf     TEXT NOT NULL,
  t      INTEGER NOT NULL,
  o      REAL NOT NULL,
  h      REAL NOT NULL,
  l      REAL NOT NULL,
  c      REAL NOT NULL,
  PRIMARY KEY (symbol, tf, t)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    TEXT,
  actor      TEXT NOT NULL CHECK (actor IN ('user', 'admin', 'system')),
  action     TEXT NOT NULL,
  trade_id   TEXT,
  meta       TEXT,
  ip         TEXT,
  created_at INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_audit_user ON audit_log(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_audit_action ON audit_log(action, created_at DESC);

CREATE TABLE IF NOT EXISTS settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);
